local function demon(ctx,e)for _,t in ipairs(ctx:card_definition(ctx:entity(e).card_id).tags or{})do if t=="demon"or t=="all"then return true end end return false end
return {api_version=1,id="EX1_596",name="Demonfire",text="Deal $2 damage to a minion. If it’s a friendly Demon, give it +2/+2 instead.",set="EXPERT1",type="spell",class="warlock",rarity="common",spell_school="fel",cost=2,target_mode="required",targets=function(ctx)return ctx:minions()end,on_play=function(ctx,self,target)if ctx:controller(target)==ctx:controller(self)and demon(ctx,target)then cardlib.effects.buff(ctx, target,2,2)else cardlib.effects.damage(ctx, target,2)end end}
